                       check_in_from, check_in_until, check_out_until, number_of_ratings, owner_id)
    VALUES ('Apartamenty Wiejska 56', 'Hel', 'Wiejska', '56', 1, 'Apartamenty Wiejska 56',
            54.604456, 18.8028956, '14:00', '22:00', '12:00', 0, (SELECT id FROM "user" WHERE role = 'HOTEL_OWNER' ORDER BY id OFFSET 123 % GREATEST((SELECT count(*) FROM "user" WHERE role = 'HOTEL_OWNER'), 1) LIMIT 1))
    ON CONFLICT (city_name, street, building_number) DO NOTHING
    RETURNING id
), r AS (
    INSERT INTO room (hotel_id, room_type, price_per_night)
    SELECT h.id, rt.id, v.price FROM h, (VALUES ('Double Room', 145), ('Family Suite', 240), ('Family Suite', 225), ('Apartment', 290), ('Apartment', 255), ('Apartment', 280)) AS v(type, price)
    JOIN room_type rt ON rt.name = v.type
)
INSERT INTO hotel_facility (hotel_id, facility_id)
SELECT h.id, f.id FROM h, (VALUES ('Swimming pool'), ('Air conditioning')) AS v(name)
JOIN facility f ON f.name = v.name;

